// useFinancialData.js
import { useState, useEffect } from 'react';

const useFinancialData = (initialData) => {
  const [financialData, setFinancialData] = useState(initialData);

  // Cargar datos al inicio desde localStorage
  useEffect(() => {
    const savedData = localStorage.getItem('financialData');
    if (savedData) {
      setFinancialData(JSON.parse(savedData));
    }
  }, []);

  // Guardar datos en localStorage cada vez que cambien
  useEffect(() => {
    localStorage.setItem('financialData', JSON.stringify(financialData));
  }, [financialData]);

  return [financialData, setFinancialData];
};

export default useFinancialData;
